function w({registerIndicator:C,nulls:g}){C({id:"oa-cci",name:"Commodity Channel Index (CCI)",category:"Momentum",placement:"pane",inputs:[{key:"length",type:"number",label:"Length",default:20,min:1,max:5e3,step:1}],plots:[{key:"cci",type:"line",title:"CCI",style:{color:"#ffeb3b",lineWidth:2}}],calc(m,v){const o=Math.max(1,Math.floor(Number(v.length)||20)),u=m.length,f=new Array(u).fill(NaN),l=new Array(o).fill(NaN);let t=0,a=0,n=0;for(let i=0;i<u;i++){const c=m[i],b=(Number(c.high)+Number(c.low)+Number(c.close))/3,e=Number.isFinite(b)?b:NaN,N=l[t];Number.isFinite(N)&&(a-=N,n-=1),Number.isFinite(e)&&(a+=e,n+=1),l[t]=e,t=(t+1)%o;const h=n>0?a/n:e;let d=0,r=0;for(let s=0;s<o;s++){const y=l[s];Number.isFinite(y)&&(d+=Math.abs(y-h),r+=1)}const p=r>0?d/r:0;f[i]=p>0?(e-h)/(.015*p):0}return{cci:g(f)}}})}export{w as default};
